import sys,json
class Solution:
    def longestPalindrome(self,s):
        bl=br=0
        for c in range(len(s)):
            l=r=c
            while l>=0 and r<len(s) and s[l]==s[r]:
                if r-l>br-bl: bl,br=l,r
                l-=1;r+=1
            l=c;r=c+1
            while l>=0 and r<len(s) and s[l]==s[r]:
                if r-l>br-bl: bl,br=l,r
                l-=1;r+=1
        return s[bl:br+1]
a=json.loads(sys.stdin.readline());print(json.dumps(Solution().longestPalindrome(a[0])))

